(function(root){'use strict';
function validate(data){if(!data||!Array.isArray(data.cards)||!Array.isArray(data.sources))throw Error('语法资料格式无效');const ids=new Set();for(const c of data.cards){if(!c||typeof c.id!=='string'||!c.id||ids.has(c.id))throw Error('语法卡 ID 缺失或重复');ids.add(c.id);for(const key of ['pattern','category','connection','meaning_zh','example_ja','translation_zh','contrast_trap','level_label'])if(typeof c[key]!=='string'||!c[key].trim())throw Error('语法卡缺少 '+key);if(!Array.isArray(c.error_tags)||c.error_tags.some(x=>typeof x!=='string')||!Array.isArray(c.exam_sources)||!Array.isArray(c.readings))throw Error('语法卡标签或来源格式无效');if(!['exam_observed','curriculum_core','foundation'].includes(c.evidence_type))throw Error('语法卡来源类型无效')}return data}
function score(card,attempts){const tags=new Set(card.error_tags);return attempts.filter(a=>a.result!=='correct'&&a.module==='grammar'&&a.error_tags.some(t=>tags.has(t))).length}
function daily(cards,attempts,date,count=8){const day=Math.floor(Date.parse(date+'T00:00:00Z')/86400000)||0;const sorted=[...cards].sort((a,b)=>a.id.localeCompare(b.id));const length=sorted.length;const ranked=sorted.map((c,i)=>({card:c,score:score(c,attempts),rotation:(i-(day%Math.max(1,length))+length)%Math.max(1,length)}));ranked.sort((a,b)=>b.score-a.score||a.rotation-b.rotation);const weak=ranked.filter(x=>x.score>0).slice(0,Math.min(5,Math.max(0,count-3)));const chosen=new Set(weak.map(x=>x.card.id));const rotation=ranked.filter(x=>!chosen.has(x.card.id)).sort((a,b)=>a.rotation-b.rotation);return [...weak,...rotation.slice(0,Math.max(0,count-weak.length))].map(x=>x.card)}
const api={validate,score,daily};root.N2Grammar=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
